INSERT INTO public.site_content (key, value) VALUES ('testimonial_groups', '[{"id":"acrylic-photos","title":"Acrylic Photos","body":"Capture every smile with our crystal-clear acrylic prints polished, vivid, and built to last for the moments you''ll always want to revisit.","videos":["__MEDIA_BASE__/3.mp4","__MEDIA_BASE__/4.mp4","__MEDIA_BASE__/10.mp4","__MEDIA_BASE__/32.mp4","__MEDIA_BASE__/34.mp4","__MEDIA_BASE__/33.mp4"]},{"id":"acrylic-clear-photos","title":"Acrylic Clear Photos","body":"Layered transparency, perfect colour fidelity, and a tactile finish that makes every photograph feel like an heirloom.","videos":["__MEDIA_BASE__/15.mp4","__MEDIA_BASE__/16.mp4","__MEDIA_BASE__/20.mp4","__MEDIA_BASE__/29.mp4","__MEDIA_BASE__/30.mp4","__MEDIA_BASE__/31.mp4"]},{"id":"creative-gifts","title":"Creative Gifts","body":"Thoughtful, personalised gifts crafted to surprise — designed around the people and stories that matter most to you.","videos":["__MEDIA_BASE__/24.mp4","__MEDIA_BASE__/14.mp4","__MEDIA_BASE__/23.mp4","__MEDIA_BASE__/7.mp4","__MEDIA_BASE__/9.mp4","__MEDIA_BASE__/22.mp4"]},{"id":"name-decors","title":"Name Decors","body":"Make any door, desk, or doorway truly yours with a custom nameplate finished in vibrant detail.","videos":["__MEDIA_BASE__/28.mp4","__MEDIA_BASE__/6.mp4","__MEDIA_BASE__/8.mp4","__MEDIA_BASE__/12.mp4","__MEDIA_BASE__/5.mp4","__MEDIA_BASE__/35.mp4"]}]'::jsonb) ON CONFLICT (key) DO NOTHING;
INSERT INTO public.site_content (key, value) VALUES ('reviews', '[{"name":"Priya S., Chennai","quote":"I ordered a customized birthday hamper from BCUBE for my sister, and it was absolutely beautiful. The packaging, personalization, and quality were beyond my expectations. Highly recommended!"},{"name":"Karthik R., Coimbatore","quote":"BCUBE handled our corporate gifting requirements perfectly. The team was professional, delivered on time, and every gift looked premium. Our clients were genuinely impressed."},{"name":"Divya M., Madurai","quote":"Their creativity is what makes BCUBE different. They suggested unique gift ideas that I hadn''t even thought of. The final product was elegant and memorable."},{"name":"Arun Kumar V., Tiruchirappalli","quote":"Excellent customer service! They patiently accommodated all my customization requests and delivered exactly what I wanted. The quality was outstanding."},{"name":"Lakshmi N., Salem","quote":"I ordered a wedding return gift package, and every guest appreciated it. The attention to detail and finishing were exceptional. Thank you, BCUBE!"},{"name":"Suresh P., Chennai","quote":"We''ve been ordering festive gifts for our employees from BCUBE for two years now. They never disappoint. Great quality, timely delivery, and excellent support."},{"name":"Keerthana R., Erode","quote":"The personalized gifts were beautifully made and arrived in perfect condition. It made our family celebration even more special. I''ll definitely order again."},{"name":"Harish K., Tirunelveli","quote":"From placing the order to receiving the package, everything was smooth. BCUBE''s team kept me updated throughout, and the final product exceeded my expectations."},{"name":"Nandhini S., Vellore","quote":"I loved the premium look and feel of the gift box. The personalization was flawless, and the recipient absolutely loved it. BCUBE truly delivers happiness."},{"name":"Praveen Raj M., Thanjavur","quote":"If you''re looking for creative and customized gifting, BCUBE is the best choice. Their designs are unique, pricing is reasonable, and the overall experience is excellent."}]'::jsonb) ON CONFLICT (key) DO NOTHING;
